import{_ as o,o as a,c as t,a0 as s}from"./chunks/framework.BQvjZmTX.js";const m=JSON.parse('{"title":"The worktree model","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/worktree-model.md","filePath":"explanation/worktree-model.md"}'),r={name:"explanation/worktree-model.md"};function c(n,e,d,h,i,p){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="the-worktree-model" tabindex="-1">The worktree model <a class="header-anchor" href="#the-worktree-model" aria-label="Permalink to &quot;The worktree model&quot;">​</a></h1><p>Why <code>project/</code> and <code>docs/</code> live as git worktrees of orphan branches inside this repo — and what that buys.</p><h2 id="the-shape" tabindex="-1">The shape <a class="header-anchor" href="#the-shape" aria-label="Permalink to &quot;The shape&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>arca/</span></span>\n<span class="line"><span>├── crates/ …           ← code branch (main)</span></span>\n<span class="line"><span>├── project/            ← worktree of the orphan `project` branch</span></span>\n<span class="line"><span>│   ├── TODO.md  BACKLOG.md  index.md  meta.toml</span></span>\n<span class="line"><span>│   └── issues/  proposals/  plans/  adrs/  handoffs/</span></span>\n<span class="line"><span>├── docs/               ← worktree of the orphan `docs` branch</span></span>\n<span class="line"><span>│   └── this site — VitePress sources</span></span>\n<span class="line"><span>└── .gitignore          ← ignores project/ and docs/</span></span></code></pre></div><p>Both worktrees share the repo&#39;s <code>.git</code> object store but have histories disjoint from <code>main</code> — orphan roots, no code ancestors. To tools they&#39;re ordinary directories; to <code>git worktree list</code> they&#39;re checkouts of their own branches.</p><h2 id="why-orphan-branches" tabindex="-1">Why orphan branches <a class="header-anchor" href="#why-orphan-branches" aria-label="Permalink to &quot;Why orphan branches&quot;">​</a></h2><p>Non-code state moves at its own cadence. On orphan branches, ledger and docs commits never touch the code history: no <code>chore: handoff T-009</code> noise in <code>main</code>&#39;s log, no PM or docs-site diffs in code PRs. Both dirs are gitignored on <code>main</code> — the worktrees physically can&#39;t leak into a code commit.</p><h2 id="why-worktrees-not-just-branches" tabindex="-1">Why worktrees (not just branches) <a class="header-anchor" href="#why-worktrees-not-just-branches" aria-label="Permalink to &quot;Why worktrees (not just branches)&quot;">​</a></h2><p>The content has to be <em>visible</em> — agents read <code>project/</code>, humans edit <code>docs/</code> — without <code>git checkout</code> swapping the code tree. Worktrees keep all three branches checked out at once.</p><h2 id="project-—-the-pm-ledger" tabindex="-1"><code>project/</code> — the PM ledger <a class="header-anchor" href="#project-—-the-pm-ledger" aria-label="Permalink to &quot;`project/` — the PM ledger&quot;">​</a></h2><p>Owned by <strong>myco</strong>, not arca: this repo dogfoods the stack&#39;s PM tool. The <code>project</code> branch history is the audit trail — every mutating <code>myco</code> verb is one atomic commit. <code>myco init</code> created the branch and worktree; agents go through <code>myco</code> verbs rather than hand-editing when a verb exists.</p><h2 id="docs-—-this-site" tabindex="-1"><code>docs/</code> — this site <a class="header-anchor" href="#docs-—-this-site" aria-label="Permalink to &quot;`docs/` — this site&quot;">​</a></h2><p>The <code>docs</code> branch holds the VitePress + Diátaxis sources; generated pages (<code>reference/cli.md</code>, <code>reference/config.md</code>, the crate map in <code>architecture.md</code>, <code>reference/crate-api.md</code>) are rebuilt by <code>docs/gen-*.py</code> and <code>arca gen-cli-docs</code> — never hand-edited. <code>cargo xtask site</code> builds the site; pushes deploy to GitHub Pages at <code>9aia.com/arca</code> via <code>scripts/deploy-docs.sh</code>.</p><p>See <a href="./architecture.html">architecture</a> for the crates the code side is made of.</p>',14)])])}const b=o(r,[["render",c]]);export{m as __pageData,b as default};
